import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# ------------------------------------------------------------
# Custom CUDA/C++ source for fused operators:
#   1) gemm (matrix multiplication + bias)
#   2) sigmoid
#   3) sum over dim=1
#   4) logsumexp over dim=0
# ------------------------------------------------------------
fused_ops_src = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <vector>

// ------------------------------------------------------------
// 1) GEMM kernel: out[i, j] = sum_{k}(x[i, k] * w[j, k]) + b[j]
//    x  shape: (B, IN)
//    w  shape: (OUT, IN)
//    b  shape: (OUT)
//    out shape: (B, OUT)
// ------------------------------------------------------------
__global__ void gemm_kernel(const float* x, const float* w, const float* b,
                            float* out, int B, int IN, int OUT) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < B * OUT) {
        int i = idx / OUT;  // row in out
        int j = idx % OUT;  // col in out
        float val = 0.0f;
        for (int k = 0; k < IN; k++) {
            val += x[i * IN + k] * w[j * IN + k];
        }
        val += b[j];
        out[idx] = val;
    }
}

torch::Tensor gemm_cuda(torch::Tensor x, torch::Tensor w, torch::Tensor b) {
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(w.is_cuda(), "w must be a CUDA tensor");
    TORCH_CHECK(b.is_cuda(), "b must be a CUDA tensor");
    TORCH_CHECK(x.dim() == 2, "x must be 2D");
    TORCH_CHECK(w.dim() == 2, "w must be 2D");
    TORCH_CHECK(b.dim() == 1, "b must be 1D");

    int B = x.size(0);
    int IN = x.size(1);
    int OUT = w.size(0);

    auto out = torch::empty({B, OUT}, x.options());

    int blocks = (B * OUT + 255) / 256;
    gemm_kernel<<<blocks, 256>>>(x.data_ptr<float>(),
                                 w.data_ptr<float>(),
                                 b.data_ptr<float>(),
                                 out.data_ptr<float>(),
                                 B, IN, OUT);
    return out;
}

// ------------------------------------------------------------
// 2) Sigmoid kernel: out[idx] = 1 / (1 + exp(-in[idx]))
// ------------------------------------------------------------
__global__ void sigmoid_kernel(const float* in, float* out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float val = in[idx];
        out[idx] = 1.0f / (1.0f + expf(-val));
    }
}

torch::Tensor sigmoid_cuda(torch::Tensor in) {
    TORCH_CHECK(in.is_cuda(), "in must be a CUDA tensor");
    auto out = torch::empty_like(in);
    int size = in.numel();
    int blocks = (size + 255) / 256;
    sigmoid_kernel<<<blocks, 256>>>(in.data_ptr<float>(),
                                    out.data_ptr<float>(),
                                    size);
    return out;
}

// ------------------------------------------------------------
// 3) Sum over dim=1 kernel: for each i in [0..B-1],
//    out[i] = sum_{j}(in[i, j])
// ------------------------------------------------------------
__global__ void sum_dim1_kernel(const float* in, float* out, int B, int H) {
    int i = blockIdx.x;  // each block handles one row
    if (i < B && threadIdx.x == 0) {
        float val = 0.0f;
        for (int j = 0; j < H; j++) {
            val += in[i * H + j];
        }
        out[i] = val;
    }
}

torch::Tensor sum_dim1_cuda(torch::Tensor in) {
    TORCH_CHECK(in.is_cuda(), "in must be a CUDA tensor");
    TORCH_CHECK(in.dim() == 2, "in must be 2D for sum over dim=1");
    int B = in.size(0);
    int H = in.size(1);
    auto out = torch::empty({B}, in.options());
    sum_dim1_kernel<<<B, 1>>>(in.data_ptr<float>(),
                              out.data_ptr<float>(),
                              B, H);
    return out;
}

// ------------------------------------------------------------
// 4) LogSumExp over dim=0 kernel: input is 1D (size=B),
//    out is scalar: out[0] = log(sum(exp(in[i])))
// ------------------------------------------------------------
__global__ void logsumexp_kernel(const float* in, float* out, int B) {
    if (threadIdx.x == 0 && blockIdx.x == 0) {
        // find max
        float max_val = in[0];
        for (int i = 1; i < B; i++) {
            if (in[i] > max_val) {
                max_val = in[i];
            }
        }
        // sum exp of shifted
        float sum_exp = 0.0f;
        for (int i = 0; i < B; i++) {
            sum_exp += expf(in[i] - max_val);
        }
        out[0] = max_val + logf(sum_exp);
    }
}

torch::Tensor logsumexp_cuda(torch::Tensor in) {
    TORCH_CHECK(in.is_cuda(), "in must be a CUDA tensor");
    TORCH_CHECK(in.dim() == 1, "in must be 1D for logsumexp over dim=0");
    int B = in.size(0);
    auto out = torch::empty({1}, in.options());
    logsumexp_kernel<<<1, 1>>>(in.data_ptr<float>(),
                               out.data_ptr<float>(),
                               B);
    return out;
}
"""

# Declare C++ function signatures
fused_ops_cpp = r"""
torch::Tensor gemm_cuda(torch::Tensor x, torch::Tensor w, torch::Tensor b);
torch::Tensor sigmoid_cuda(torch::Tensor in);
torch::Tensor sum_dim1_cuda(torch::Tensor in);
torch::Tensor logsumexp_cuda(torch::Tensor in);
"""

# Build and load the fused ops
fused_ops = load_inline(
    name="fused_ops",
    cpp_sources=fused_ops_cpp,
    cuda_sources=fused_ops_src,
    functions=[
        "gemm_cuda",
        "sigmoid_cuda",
        "sum_dim1_cuda",
        "logsumexp_cuda",
    ],
    verbose=False
)

# ------------------------------------------------------------
# Optimized model using the custom CUDA operators
# ------------------------------------------------------------
class ModelNew(nn.Module):
    """
    Model that performs the same operations as the original:
    1) linear1 (Gemm)
    2) Sigmoid
    3) Sum over dim=1
    4) LogSumExp over dim=0
    but with custom CUDA kernels.
    """
    def __init__(self, input_size, hidden_size, output_size):
        super(ModelNew, self).__init__()
        # We'll replicate nn.Linear with our own parameters:
        # linear1 weight shape: (hidden_size, input_size)
        # linear1 bias shape: (hidden_size,)
        self.weight1 = nn.Parameter(torch.randn(hidden_size, input_size).cuda())
        self.bias1 = nn.Parameter(torch.randn(hidden_size).cuda())
        # linear2 is unused in original forward, but we keep it to match signature
        self.weight2 = nn.Parameter(torch.randn(output_size, hidden_size).cuda())
        self.bias2 = nn.Parameter(torch.randn(output_size).cuda())

    def forward(self, x):
        # Equivalent to x = self.linear1(x)
        x = fused_ops.gemm_cuda(x, self.weight1, self.bias1)
        # Equivalent to x = torch.sigmoid(x)
        x = fused_ops.sigmoid_cuda(x)
        # Equivalent to x = torch.sum(x, dim=1)
        x = fused_ops.sum_dim1_cuda(x)
        # Equivalent to x = torch.logsumexp(x, dim=0)
        x = fused_ops.logsumexp_cuda(x)
        return x

