    batch_size = 128
    input_size = 10
    return [torch.randn(batch_size, input_size).cuda()]

def get_init_inputs():
    # Must match the original: returns [input_size, hidden_size, output_size]
    input_size = 10
    hidden_size = 20
    output_size = 5
    return [input_size, hidden_size, output_size]
